is_a_function = {(1, "a"), (2, "b"), (3, "a")}   # fine: every input has one output
not_a_function = {(1, "a"), (1, "b")}             # 1 maps to two different outputs

def is_function(relation: set) -> bool:
    seen_inputs = {}
    for (a, b) in relation:
        if a in seen_inputs and seen_inputs[a] != b:
            return False
        seen_inputs[a] = b
    return True

print(is_function(is_a_function))   # True
print(is_function(not_a_function))  # False

def is_surjective(pairs: list, codomain: set) -> bool:
    outputs = {b for (a, b) in pairs}
    return outputs == codomain

f_pairs = [(-2, 4), (-1, 1), (0, 0), (1, 1), (2, 4)]
print(is_surjective(f_pairs, {0, 1, 4, 9, 16}))  # False, only hits {0, 1, 4}
print(is_surjective(f_pairs, {0, 1, 4}))          # True, matches the range exactly

