def identity(x):
    return x

def f(x):
    return 2 * x + 5

print(compose(f, identity)(10))  # f(identity(10)) = f(10) = 25
print(compose(identity, f)(10))  # identity(f(10)) = f(10) = 25

def double(x):
    return 2 * x

def halve(x):
    return x / 2

print(halve(double(5)))  # 5.0, halve undoes double exactly
print(double(halve(5)))  # 5.0, works in the other order too

